  const productCard = (p, index=0) => `<article class="product-card" style="animation-delay:${Math.min(index*45,250)}ms"><button class="product-picture" data-action="navigate" data-route="product/${p.id}" aria-label="Открыть ${escapeHTML(p.title)}">${pImage(p)}${p.badge?`<span class="photo-label">${escapeHTML(p.badge)}</span>`:''}</button><button class="fav-btn ${isFav(p.id)?'on':''}" data-action="favorite" data-id="${p.id}" aria-label="${isFav(p.id)?'Убрать из избранного':'В избранное'}">${icon('heart',18)}</button><div class="product-meta"><div class="product-price">${money(p.price)}${p.oldPrice?`<span class="old-price">${money(p.oldPrice)}</span>`:''}</div><button class="product-title" data-action="navigate" data-route="product/${p.id}">${escapeHTML(p.title)}</button><button class="product-seller" data-action="navigate" data-route="community/${p.seller}">${escapeHTML(community(p.seller).name)}</button><div class="card-actions">${p.stock?`<span class="subtle-stock">${p.stock<4?'Мало осталось':'В наличии'}</span>`:'<span class="out-stock">Нет в наличии</span>'}<button class="circle-action" data-action="add-cart" data-id="${p.id}" ${p.stock?'':'disabled'} aria-label="Добавить в корзину">${icon('plus',18)}</button></div></div></article>`;
  const productsGrid = (arr) => `<div class="products-grid">${arr.map(productCard).join('')}</div>`;
  const dropLabel = (d) => d.status==='live'?'Уже в продаже':d.status==='soldout'?'Распродано':d.status==='ended'?'Завершён':'Скоро старт';
  const dropCard = (d, large=false) => `<button class="drop-card ${large?'drop-large':''}" data-action="navigate" data-route="drop/${d.id}"><div class="drop-image" style="--visual:${d.seller==='archive'?'#d2d8df':'#e5ddd2'}">${illustration(product(d.itemIds[0])||model.products[0])}<img src="${escapeHTML(d.cover)}" alt="" loading="lazy" onerror="this.style.display='none'" /></div><div class="drop-overlay"><span class="drop-badge">${icon('fire',14)} ${dropLabel(d)}</span><div><span class="drop-by">${escapeHTML(community(d.seller).name)}</span><h3>${escapeHTML(d.title)}</h3><p>${escapeHTML(d.subtitle)}</p><span class="drop-link">${d.status==='announced'?dateLabel(d.startsAt,true):'Смотреть коллекцию'} ${icon('arrow',15)}</span></div></div></button>`;
  const pageIntro = (eyebrow,title,sub,actions='') => `<div class="page-intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="page-tools">${actions}</div>`:''}</div>`;
  const sectionHeader = (title,sub='',link='',to='') => `<div class="section-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<button class="text-link" data-action="navigate" data-route="${to}">${link} ${icon('arrow',16)}</button>`:''}</div>`;
  const market = () => `<div class="market-page"><div class="hero"><div class="hero-text"><span class="hero-overline">НОВОЕ В VK МАРКЕТЕ <span class="hero-star">✦</span></span><h1>Находки, у которых<br/>есть <em>история</em></h1><p>Покупайте у любимых сообществ, открывайте новые бренды и не пропускайте лимитированные дропы.</p><div class="hero-actions">${button(`Найти своё ${icon('arrow',18)}`,'open-search','primary btn-lg')}${button(`Смотреть дропы ${icon('fire',17)}`,'scroll-drops','light btn-lg')}</div></div><div class="hero-image" role="img" aria-label="Коллекция дизайнерских предметов">${illustration(model.products[3])}<img src="${photos.chair}" alt="Дизайнерский стул"/><div class="hero-floating"><span class="float-icon">${icon('spark',17)}</span><div>Из сообществ VK<br/><strong>Вещи с характером</strong></div></div></div><span class="hero-shape one"></span><span class="hero-shape two"></span></div><div class="benefits"><span>${icon('check',17)} Продавцы из сообществ VK</span><span>${icon('heart',17)} Находки и малые бренды</span><span>${icon('bell',17)} Уведомления о дропах</span></div><section class="block" id="categories">${sectionHeader('Найдите то, что нравится','Пять направлений — тысячи идей')}<div class="category-row">${[['Гардероб','👕','#f2e2ea'],['Дом и дача','⌂','#e6e9da'],['Хобби и развлечения','✦','#eee5ff'],['Продукты питания','◉','#fff0d9'],['Красота и здоровье','✿','#f7e5e3']].map(([n,g,c])=>`<button class="category-tile" data-action="category" data-name="${n}"><span class="category-art" style="background:${c}">${g}</span><span>${n}</span>${icon('arrow',15)}</button>`).join('')}</div></section><section class="block" id="drops">${sectionHeader('Дропы, которые ждут','Ограниченные коллекции из ваших сообществ','Все дропы','studio/drops')}<div class="drop-grid">${model.drops.slice(0,2).map(d=>dropCard(d)).join('')}</div></section><section class="block">${sectionHeader('Вам может понравиться','Необычные товары от независимых продавцов','Смотреть всё','search')}${productsGrid(model.products.slice(0,8))}</section><section class="block">${sectionHeader('Магазины с характером','За каждым товаром — люди и сообщество')}<div class="community-grid">${communities.map(s=>`<button class="community-tile" data-action="navigate" data-route="community/${s.id}">${sellerAvatar(s,'large')}<div><strong>${escapeHTML(s.name)}</strong><p>${escapeHTML(s.category)}</p><small>${s.followers} подписчиков</small></div>${icon('arrow',18)}</button>`).join('')}</div></section></div>`;
  const filteredProducts = () => {let arr = model.products.filter(p=> (ui.category==='Все'||p.category===ui.category) && (!ui.query||`${p.title} ${community(p.seller).name} ${p.description}`.toLowerCase().includes(ui.query.toLowerCase())) && (!ui.inStock||p.stock>0) && (!ui.maxPrice||p.price<=Number(ui.maxPrice))); if(ui.sort==='cheap')arr.sort((a,b)=>a.price-b.price); if(ui.sort==='expensive')arr.sort((a,b)=>b.price-a.price); return arr;};
  const search = () => `<div class="search-page">${pageIntro('КАТАЛОГ','Поиск товаров','Выбирайте вещи, которые подходят именно вам.')}<div class="search-layout"><aside class="filters panel"><div class="filter-title">${icon('filter',18)} Фильтры</div><label>Категория<select id="filter-category" data-filter="category">${['Все','Продукты питания','Хобби и развлечения','Дом и дача','Гардероб','Красота и здоровье'].map(c=>`<option ${ui.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Цена до, ₽<input id="filter-price" data-filter="maxPrice" type="number" min="0" placeholder="Любая" value="${escapeHTML(ui.maxPrice)}" /></label><label class="check-row"><input type="checkbox" data-filter="inStock" ${ui.inStock?'checked':''}/> Только в наличии</label><button class="subtle-button" data-action="clear-filters">Сбросить фильтры</button></aside><div class="search-results"><div class="results-top"><strong>${fmt.format(filteredProducts().length)} товаров</strong><label>Сортировка <select data-filter="sort"><option value="popular" ${ui.sort==='popular'?'selected':''}>Популярные</option><option value="cheap" ${ui.sort==='cheap'?'selected':''}>Сначала дешевле</option><option value="expensive" ${ui.sort==='expensive'?'selected':''}>Сначала дороже</option></select></label></div>${filteredProducts().length?productsGrid(filteredProducts()):empty('search','Ничего не найдено','Попробуйте изменить запрос или сбросить фильтры.','clear-filters','Сбросить фильтры')}</div></div></div>`;
  const breadcrumb = (back,title) => `<button class="breadcrumb" data-action="navigate" data-route="${back}">${icon('back',17)} ${title}</button>`;
  const productPage = (id) => { const p=product(id); if(!p)return notFound(); const s=community(p.seller);return `<div class="detail-page">${breadcrumb('search','К каталогу')}<div class="product-detail panel"><div class="detail-gallery">${pImage(p,'detail-photo')}<div class="thumb-row"><span class="selected-thumb">${pImage(p)}</span><span class="detail-placeholder">${icon('spark',22)} <small>Детали товара</small></span></div></div><div class="detail-content"><div class="eyebrow">${escapeHTML(p.category)}</div><h1>${escapeHTML(p.title)}</h1><div class="detail-price">${money(p.price)}${p.oldPrice?`<s>${money(p.oldPrice)}</s>`:''}</div><div class="availability ${p.stock?'':'out-stock'}">${icon(p.stock?'check':'info',16)} ${p.stock?`В наличии · ${p.stock} шт.`:'Нет в наличии'}</div>${p.badge?`<div class="tag-row">${badge(p.badge,'soft')}</div>`:''}<div class="detail-buy">${button(`${icon('cart',19)} В корзину`,'add-cart','primary btn-lg',`data-id="${p.id}" ${p.stock?'':'disabled'}`)}${button(icon('heart',20),'favorite',isFav(id)?'outline favorited btn-lg':'outline btn-lg',`data-id="${p.id}" aria-label="В избранное"`)}</div><div class="detail-fine">${icon('truck',17)} Способ доставки и оплаты — при оформлении заказа</div><div class="separator"></div><div class="seller-summary">${sellerAvatar(s)}<div><strong>${escapeHTML(s.name)}</strong><span>${s.followers} подписчиков</span></div><button class="text-link" data-action="navigate" data-route="community/${s.id}">О продавце ${icon('chevron',16)}</button></div><p class="detail-description">${escapeHTML(p.description)}</p>${p.size?`<p class="spec-row"><span>Размер</span><strong>${escapeHTML(p.size)}</strong></p>`:''}${p.condition?`<p class="spec-row"><span>Состояние</span><strong>${escapeHTML(p.condition)}</strong></p>`:''}<p class="spec-row"><span>Категория</span><strong>${escapeHTML(p.category)}</strong></p><div class="seller-link"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('external',16)} Открыть сообщество VK</a><span>В демо переход ведёт на главную VK</span></div></div></div><section class="block">${sectionHeader('От этого продавца')}${productsGrid(model.products.filter(x=>x.seller===p.seller && x.id!==p.id).slice(0,4))}</section></div>`;};
  const communityPage = (id) => {const s=community(id);return `<div class="community-page">${breadcrumb('market','К Маркету')}<div class="community-hero panel"><div class="community-banner" style="--community-accent:${s.color}"><div class="big-watermark">${escapeHTML(s.avatar)}</div></div><div class="community-body">${sellerAvatar(s,'huge')}<div class="community-heading"><div><div class="eyebrow">МАГАЗИН ИЗ СООБЩЕСТВА</div><h1>${escapeHTML(s.name)} <span class="verified">${icon('check',13)}</span></h1><p>${escapeHTML(s.description)}</p><div class="community-hint">${s.followers} подписчиков · ${model.products.filter(p=>p.seller===id).length} товаров</div></div><div class="community-actions">${button(`${icon('heart',18)} ${model.following.includes(id)?'Вы подписаны':'Подписаться'}`,'follow',model.following.includes(id)?'outline':'primary',`data-id="${id}"`)}<a class="btn light" href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('external',17)} Сообщество VK</a></div></div></div></div><section class="block">${sectionHeader('Товары магазина')}${productsGrid(model.products.filter(p=>p.seller===id))}</section></div>`;};
  const favorites = () => {const list=model.products.filter(p=>model.favorites.includes(p.id));return `<div>${pageIntro('ЛИЧНАЯ ПОДБОРКА','Избранное','Сохраняйте понравившееся, чтобы вернуться к нему позже.')}${list.length?productsGrid(list):empty('heart','Пока ничего нет','Нажмите на сердечко у товара — он появится здесь.','open-search','Искать товары')}${model.following.length?`<section class="block">${sectionHeader('Ваши подписки')}<div class="community-grid">${communities.filter(s=>model.following.includes(s.id)).map(s=>`<button class="community-tile" data-action="navigate" data-route="community/${s.id}">${sellerAvatar(s)}<strong>${escapeHTML(s.name)}</strong>${icon('arrow',18)}</button>`).join('')}</div></section>`:''}</div>`;};
  const cartTotal = () => model.cart.reduce((sum,x)=>sum+(product(x.id)?.price||0)*x.qty,0);
  const cart = () => `<div>${pageIntro('ПОКУПКИ','Корзина','Оформление заказа в рамках одного магазина.')}${model.cart.length?`<div class="cart-layout"><div class="panel cart-list">${model.cart.map(item=>{const p=product(item.id);if(!p)return '';return `<div class="cart-item">${pImage(p)}<div class="cart-text"><button class="product-title" data-action="navigate" data-route="product/${p.id}">${escapeHTML(p.title)}</button><span class="muted">${escapeHTML(community(p.seller).name)}</span><strong>${money(p.price)}</strong><button class="remove-item" data-action="remove-cart" data-id="${p.id}">Удалить</button></div><div class="qty-controls"><button data-action="qty-down" data-id="${p.id}" aria-label="Уменьшить">${icon('minus',16)}</button><span>${item.qty}</span><button data-action="qty-up" data-id="${p.id}" aria-label="Увеличить">${icon('plus',16)}</button></div></div>`;}).join('')}</div><aside class="panel order-summary"><h3>Ваш заказ</h3><p>${model.cart.reduce((s,x)=>s+x.qty,0)} товара</p><div class="summary-line"><span>Товары</span><b>${money(cartTotal())}</b></div><div class="summary-line"><span>Доставка</span><span>Уточним позже</span></div><div class="summary-total"><span>Итого</span><strong>${money(cartTotal())}</strong></div>${button(`Перейти к оформлению ${icon('arrow',18)}`,'checkout','primary btn-wide btn-lg')}<small>Это демо. Реальные платежи не выполняются.</small></aside></div>`:empty('cart','Корзина пуста','Добавьте товар из каталога — и он появится здесь.','open-search','Перейти в каталог')}</div>`;
  const orderStatusClass = (st) => st==='Завершён'?'success':st==='Отменён'?'danger':st==='Новый'?'blue':'soft';
  const ordersList = (seller=false) => {const arr=seller?model.orders.filter(o=>o.seller==='archive'):model.orders;return arr.length?`<div class="orders-list">${arr.slice().reverse().map(o=>`<div class="order-card panel"><div class="order-info"><div><strong>Заказ № ${escapeHTML(o.id)}</strong><p>${dateLabel(o.createdAt,true)} · ${escapeHTML(community(o.seller).name)}</p></div>${badge(o.status,orderStatusClass(o.status))}</div><div class="order-products">${o.items.map(i=>{const p=product(i.id);return `<span>${escapeHTML(p?.title||i.id)} × ${i.qty}</span>`;}).join('')}</div><div class="order-bottom"><strong>${money(o.total)}</strong><span class="order-payment">${icon('info',15)} Оплата не подключена (демо)</span>${seller&&o.status!=='Завершён'&&o.status!=='Отменён'?`<div class="order-controls">${button('Следующий статус','next-order','outline',`data-id="${o.id}"`)}${button('Отменить','cancel-order','ghost',`data-id="${o.id}"`)}</div>`:''}</div></div>`).join('')}</div>`:empty('bag','Заказов пока нет',seller?'Как только покупатель оформит демозаказ, он появится здесь.':'Заказы появятся здесь после оформления первой покупки.',seller?'switch-buyer':'open-search',seller?'Открыть Маркет':'Найти товары');};
  const profile = () => `<div>${pageIntro('ВАШ ПРОФИЛЬ','Личный кабинет','Все покупки, избранные товары и подписки в одном месте.')}<div class="profile-grid"><div class="profile-card panel"><span class="profile-avatar">ВК</span><div><h2>Пользователь VK</h2><p>Демонстрационный аккаунт</p></div>${badge('Прототип','soft')}</div><button class="profile-shortcut panel" data-action="navigate" data-route="orders">${icon('bag',24)}<strong>Мои заказы</strong><span>${model.orders.length} заказов</span>${icon('arrow',18)}</button><button class="profile-shortcut panel" data-action="navigate" data-route="favorites">${icon('heart',24)}<strong>Избранное</strong><span>${model.favorites.length} товаров</span>${icon('arrow',18)}</button><button class="profile-shortcut panel" data-action="navigate" data-route="studio/overview">${icon('chart',24)}<strong>Кабинет продавца</strong><span>Управлять магазином</span>${icon('arrow',18)}</button></div><div class="panel settings-inline"><div><strong>Напоминания о дропах</strong><p>В прототипе сохраняется только ваше согласие на напоминание.</p></div><label class="switch"><input type="checkbox" data-setting="notifications" ${model.notifications?'checked':''} /><span></span></label></div>${model.orders.length?`<section class="block">${sectionHeader('Последние заказы','','Все заказы','orders')}${ordersList(false)}</section>`:''}</div>`;
  const dropsPage = (id) => {const d=drop(id);if(!d)return notFound();const s=community(d.seller);const live=d.status==='live';const finished=['soldout','ended'].includes(d.status);return `<div class="drop-page">${breadcrumb('market','К Маркету')}<div class="drop-head panel"><div class="drop-cover" style="--visual:#e5e2db">${illustration(product(d.itemIds[0])||model.products[0])}<img src="${escapeHTML(d.cover)}" alt="${escapeHTML(d.title)}" onerror="this.style.display='none'"/></div><div class="drop-info">${badge(dropLabel(d),live?'success':finished?'soft':'blue')}<p class="eyebrow">ЛИМИТИРОВАННАЯ КОЛЛЕКЦИЯ</p><h1>${escapeHTML(d.title)}</h1><p class="drop-subtitle">${escapeHTML(d.subtitle)}</p><div class="seller-mini">${sellerAvatar(s)} <strong>${escapeHTML(s.name)}</strong></div><p class="drop-description">${escapeHTML(d.description)}</p>${d.status==='announced'?`<div class="countdown-box"><span>До старта осталось</span><strong data-countdown="${d.id}">${countdown(d.startsAt)}</strong><small>Старт: ${dateLabel(d.startsAt,true)}</small></div>${button(`${icon('bell',18)} ${model.reminders.includes(d.id)?'Напоминание включено':'Напомнить о запуске'}`,'remind',model.reminders.includes(d.id)?'outline btn-lg':'primary btn-lg',`data-id="${d.id}"`)}`:live?`<div class="live-box">${icon('check',18)} Дроп открыт — товары доступны к покупке</div>`:`<div class="live-box muted">Коллекция завершена. Следите за следующими запусками.</div>`}<p class="demo-explain">Уведомления и запуск имитируются внутри браузера.</p></div></div><section class="block">${sectionHeader('В коллекции',`${d.itemIds.length} товара · ${live?'можно заказать':finished?'дроп завершён':'продажи ещё не начались'}`)}<div class="products-grid">${d.itemIds.map((id,i)=>{const p=product(id);if(!p)return '';return `<div class="drop-product-wrap">${productCard(p,i)}${!live?`<div class="drop-locked">${icon(finished?'check':'clock',17)} ${finished?'Дроп завершён':'Продажи с начала дропа'}</div>`:''}</div>`;}).join('')}</div></section></div>`;};
  const notFound = () => empty('search','Страница не найдена','Откройте Маркет, чтобы продолжить.','switch-buyer','Открыть Маркет');
  const statCard = (title,value,delta,glyph) => `<div class="stat-card panel"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(glyph,19)}</span></div><strong>${value}</strong><small>${delta}</small></div>`;
  const overview = () => {const active=model.orders.filter(o=>o.status!=='Отменён');const revenue=active.reduce((s,o)=>s+o.total,0);const low=model.products.filter(p=>p.seller==='archive'&&p.stock<=2);return `<div>${pageIntro('КАБИНЕТ ПРОДАВЦА','Обзор магазина',`Добро пожаловать обратно. Вот что происходит в «Архив 92».`,button(`${icon('plus',18)} Добавить товар`,'new-product','primary'))}${!model.connected?`<div class="notice">Сообщество не подключено. <button data-action="navigate" data-route="studio/settings">Настроить подключение</button></div>`:''}<div class="stats-grid">${statCard('Заказов',fmt.format(active.length),'+ новые заказы за время демо','bag')}${statCard('Сумма заказов',money(revenue),'Не является оплаченной выручкой','wallet')}${statCard('Товаров в каталоге',fmt.format(model.products.filter(p=>p.seller==='archive').length),'Опубликованные товары','box')}${statCard('Скоро дроп',fmt.format(model.drops.filter(d=>d.seller==='archive'&&d.status==='announced').length),'Запланированные коллекции','fire')}</div><div class="dashboard-grid"><section class="panel dashboard-section"><div class="section-header"><h2>Последние заказы</h2><button class="text-link" data-action="navigate" data-route="studio/orders">Все заказы ${icon('arrow',16)}</button></div>${active.length?`<div class="mini-orders">${active.slice(-3).reverse().map(o=>`<div><span>№ ${o.id}</span><strong>${money(o.total)}</strong>${badge(o.status,orderStatusClass(o.status))}</div>`).join('')}</div>`:empty('bag','Новых заказов нет','Оформите демозаказ в покупательской части.','switch-buyer','Перейти в Маркет')}</section><section class="panel dashboard-section"><div class="section-header"><h2>Ближайшие дропы</h2><button class="text-link" data-action="navigate" data-route="studio/drops">Управление ${icon('arrow',16)}</button></div>${model.drops.filter(d=>d.seller==='archive').slice(0,1).map(d=>`<div class="next-drop">${pImage(product(d.itemIds[0]))}<div><strong>${escapeHTML(d.title)}</strong><p>${dropLabel(d)}</p><small>${dateLabel(d.startsAt,true)}</small></div></div>`).join('')||'<p>Пока нет дропов.</p>'}</section></div><section class="block">${sectionHeader('Товары, требующие внимания','У этих позиций заканчивается остаток','В каталог','studio/products')}<div class="low-stock-grid">${low.map(p=>`<button class="low-stock" data-action="navigate" data-route="studio/products">${pImage(p)}<div><b>${escapeHTML(p.title)}</b><span>Осталось: ${p.stock} шт.</span></div>${icon('arrow',16)}</button>`).join('')||'<div class="panel muted pad">Все остатки в норме</div>'}</div></section></div>`;};
  const sellerProducts = () => {const list=model.products.filter(p=>p.seller==='archive');return `<div>${pageIntro('МАГАЗИН · АРХИВ 92','Товары',`Редактируйте каталог, цены и остатки.`,button(`${icon('plus',18)} Добавить товар`,'new-product','primary'))}<div class="panel table-panel"><div class="table-top"><strong>${list.length} товаров</strong><span>Данные сохранены в этом браузере</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Товар</th><th>Категория</th><th>Цена</th><th>Остаток</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="table-product">${pImage(p)}<span>${escapeHTML(p.title)}</span></div></td><td>${escapeHTML(p.category)}</td><td><strong>${money(p.price)}</strong></td><td><div class="stock-editor"><button data-action="stock-down" data-id="${p.id}" aria-label="Уменьшить остаток">${icon('minus',15)}</button><b>${p.stock}</b><button data-action="stock-up" data-id="${p.id}" aria-label="Увеличить остаток">${icon('plus',15)}</button></div></td><td><button class="icon-btn" title="Редактировать" data-action="edit-product" data-id="${p.id}">${icon('edit',18)}</button></td></tr>`).join('')}</tbody></table></div></div></div>`;};
  const sellerOrders = () => `<div>${pageIntro('МАГАЗИН · АРХИВ 92','Заказы','Меняйте статусы и отслеживайте выполнение демонстрационных заказов.')}${ordersList(true)}</div>`;
  const sellerDrops = () => `<div>${pageIntro('МАГАЗИН · АРХИВ 92','Дропы','Запускайте небольшие коллекции и собирайте интерес заранее.',button(`${icon('plus',18)} Создать дроп`,'new-drop','primary'))}<div class="seller-drop-list">${model.drops.filter(d=>d.seller==='archive').map(d=>`<div class="panel seller-drop-row"><div class="seller-drop-photo"><img src="${escapeHTML(d.cover)}" alt="" onerror="this.style.display='none'"/></div><div class="seller-drop-text">${badge(dropLabel(d),d.status==='live'?'success':'soft')}<h3>${escapeHTML(d.title)}</h3><p>${d.itemIds.length} товара · ${dateLabel(d.startsAt,true)}</p><small>${model.reminders.includes(d.id)?'Вы подписались на уведомление':'Напоминания доступны покупателям'}</small></div><div class="seller-drop-actions">${button('Посмотреть','view-drop','outline',`data-id="${d.id}"`)}${d.status==='announced'?button(`${icon('fire',16)} Запустить демо`,'launch-drop','primary',`data-id="${d.id}"`):d.status==='live'?button('Завершить дроп','end-drop','outline',`data-id="${d.id}"`):''}</div></div>`).join('')||empty('fire','Нет дропов','Создайте первую лимитированную коллекцию.','new-drop','Создать дроп')}</div><div class="notice">${icon('info',17)} В живой версии старт должен зависеть от времени, часового пояса и серверного остатка. Здесь запуск включается вручную для демонстрации.</div></div>`;
  const analyticsDataset = () => {let posts=demoPosts.filter(x=>ui.analyticsProduct==='all'||x.product===ui.analyticsProduct);const factor=ui.period===7?.29:ui.period===90?2.35:1;const sum=(field)=>Math.round(posts.reduce((s,p)=>s+p[field],0)*factor);return {posts,views:sum('views'),opens:sum('opens'),orders:sum('orders'),paid:sum('paid'),factor};};
  const areaChart = (period,metric) => {const count=period===7?7:period===90?14:12;const ys=Array.from({length:count},(_,i)=>[22,35,28,51,43,62,50,70,59,82,68,94,74,88][i]||60).map((n,i)=>Math.max(10,n+(metric==='orders'?-10:0)+(period===7?i*2:0)));const coords=ys.map((v,i)=>[32+i*644/(count-1),188-v*1.55]);const path=coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');return `<svg class="area-chart" viewBox="0 0 710 215" role="img" aria-label="Динамика ${metric==='orders'?'заказов':'открытий'} за ${period} дней"><defs><linearGradient id="areaFade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#0077ff" stop-opacity=".22"/><stop offset="1" stop-color="#0077ff" stop-opacity="0"/></linearGradient></defs>${[42,89,136,183].map(y=>`<line x1="32" x2="678" y1="${y}" y2="${y}" stroke="currentColor" stroke-opacity=".1" stroke-dasharray="5 6"/>`).join('')}<path d="${path} L676 199 L32 199 Z" fill="url(#areaFade)"/><path d="${path}" fill="none" stroke="#0077ff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${coords.map(([x,y],i)=>i===coords.length-1?`<circle cx="${x}" cy="${y}" r="5" fill="#0077ff" stroke="white" stroke-width="3"/>`:'').join('')}</svg>`;};
  const demographic = () => {const age=[['<18',4,4],['18–24',28,21],['25–34',22,13],['35–44',6,5],['45–54',2,1],['55+',1,1]];return `<div class="demographic-bars">${age.map(([l,m,f])=>`<div class="age-column"><div class="age-bars"><span class="age-male" style="height:${m/28*100}%" title="Мужчины ${m}%"></span><span class="age-female" style="height:${f/28*100}%" title="Женщины ${f}%"></span></div><small>${l.replace('<','&lt;')}</small></div>`).join('')}</div><div class="chart-legend"><span><i class="dot blue"></i> Мужчины · 58%</span><span><i class="dot pink"></i> Женщины · 42%</span></div>`;};
